-- ── Miami Cigar & Co. ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('et l''atlas le classe là où se roule la ligne qui porte son nom : Estelí, chez My Father.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'et l''atlas le classe là où se roule la ligne qui porte son nom : Estelí, chez My Father.', 'et l''atlas le classe là où se roule la ligne qui porte le nom du fondateur, Nestor Miranda : Estelí, chez My Father. Le nombre ne tranche pas : sur les quatre marques que la maison présente en octobre 2026, Nestor Miranda et Don Lino (série Africa, chez A.J. Fernandez) se roulent au Nicaragua, Tatiana et Outcast en République dominicaine — Tatiana, que Cigar Coop décrit en juillet 2023 comme la marque de fond de la maison, à La Aurora, dit Cigar Coop de la Delights en mai 2024 et Neptune Cigar des autres ; Outcast sans fabrique nommée — et aucune page ne donne de volume par fabrique.'), `history`),
  `history_en` = IF(LOCATE(CAST('and this atlas classifies it where the line bearing its name is rolled: Estelí, at My Father.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'and this atlas classifies it where the line bearing its name is rolled: Estelí, at My Father.', 'and this atlas classifies it where the line bearing the founder''s name, Nestor Miranda, is rolled: Estelí, at My Father. The count does not settle it: of the four brands the house presents in October 2026, Nestor Miranda and Don Lino (Africa series, at A.J. Fernandez) are rolled in Nicaragua, Tatiana and Outcast in the Dominican Republic — Tatiana, which Cigar Coop describes in July 2023 as the house''s mainstay brand, at La Aurora, says Cigar Coop of the Delights in May 2024 and Neptune Cigar of the others; Outcast with no factory named — and no page gives a volume by factory.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('y este atlas lo clasifica donde se lía la línea que lleva su nombre: Estelí, en My Father.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'y este atlas lo clasifica donde se lía la línea que lleva su nombre: Estelí, en My Father.', 'y este atlas lo clasifica donde se lía la línea que lleva el nombre del fundador, Nestor Miranda: Estelí, en My Father. El número no zanja la cuestión: de las cuatro marcas que la casa presenta en octubre de 2026, Nestor Miranda y Don Lino (serie Africa, en A.J. Fernandez) se lían en Nicaragua, Tatiana y Outcast en la República Dominicana — Tatiana, que Cigar Coop describe en julio de 2023 como la marca de base de la casa, en La Aurora, dice Cigar Coop de la Delights en mayo de 2024 y Neptune Cigar de las demás; Outcast sin fábrica nombrada — y ninguna página da un volumen por fábrica.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('und dieser Atlas ordnet ihn dort ein, wo die Linie mit seinem Namen gerollt wird: Estelí, bei My Father.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'und dieser Atlas ordnet ihn dort ein, wo die Linie mit seinem Namen gerollt wird: Estelí, bei My Father.', 'und dieser Atlas ordnet ihn dort ein, wo die Linie mit dem Namen des Gründers, Nestor Miranda, gerollt wird: Estelí, bei My Father. Die Zahl gibt nicht den Ausschlag: Von den vier Marken, die das Haus im Oktober 2026 vorstellt, werden Nestor Miranda und Don Lino (Serie Africa, bei A.J. Fernandez) in Nicaragua gerollt, Tatiana und Outcast in der Dominikanischen Republik — Tatiana, die Cigar Coop im Juli 2023 als Basismarke des Hauses beschreibt, bei La Aurora, sagt Cigar Coop von der Delights im Mai 2024 und Neptune Cigar von den anderen; Outcast ohne genannte Fabrik — und keine Seite nennt ein Volumen je Fabrik.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集按其同名系列的卷制地归类：埃斯特利，My Father 厂。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集按其同名系列的卷制地归类：埃斯特利，My Father 厂。', '本图集按其以创始人 Nestor Miranda 命名的系列的卷制地归类：埃斯特利，My Father 厂。数量无法裁定：公司在2026年10月介绍的四个品牌中，Nestor Miranda 与 Don Lino（Africa 系列，由 A.J. Fernandez 制作）在尼加拉瓜卷制，Tatiana 与 Outcast 在多米尼加共和国卷制——Tatiana 是 Cigar Coop 在2023年7月描述为公司基础品牌的那一个，在 La Aurora 卷制，Cigar Coop 在2024年5月就 Delights 如此说，Neptune Cigar 则就其余各款如此说；Outcast 未点名工厂——而且没有任何一页给出按工厂划分的产量。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('ويصنّفه هذا الأطلس حيث يُلفّ الخطّ الذي يحمل اسمه: إستيلي، لدى My Father.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'ويصنّفه هذا الأطلس حيث يُلفّ الخطّ الذي يحمل اسمه: إستيلي، لدى My Father.', 'ويصنّفه هذا الأطلس حيث يُلفّ الخطّ الذي يحمل اسم المؤسّس، Nestor Miranda: إستيلي، لدى My Father. والعدد لا يحسم الأمر: فمن بين العلامات الأربع التي تقدّمها الدار في تشرين الأول/أكتوبر 2026، يُلفّ Nestor Miranda وDon Lino (سلسلة Africa، لدى A.J. Fernandez) في نيكاراغوا، وTatiana وOutcast في جمهورية الدومينيكان — وTatiana، التي تصفها Cigar Coop في تموز/يوليو 2023 بأنها العلامة الأساسية للدار، لدى La Aurora، بحسب ما تقول Cigar Coop عن Delights في أيار/مايو 2024 وNeptune Cigar عن البقية؛ أمّا Outcast فلا مصنع مسمّى لها — ولا تعطي أي صفحة حجمًا للإنتاج بحسب المصنع.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Miami Cigar & Co.';

