heim ; roulée chez Tabacalera Altagracia, Santiago.","name":"Laura Chavin","iconic":false},{"desc":"Kopp Tobaccos (ex-Kohlhase & Kopp), Rellingen — bundles Red, Blue, Amber ; fabrique dominicaine non nommée.","name":"Mustique","iconic":false},{"desc":"Don Emmanuel (Brésil) ; ligne Anunnaki, roulée chez Eladio Díaz à Santiago de los Caballeros","name":"Don Emmanuel","iconic":false},{"desc":"2017 — maison de Houston ; Jazz, Red Tail et Prophecy chez La Aurora, Natural Pleasure chez Agrotabacos.","name":"Emperors Cut","iconic":false},{"desc":"2006 ou 2007 — marque de David Garofalo (United Cigars), roulée chez Tabacalera Magia Cubana, Santiago","name":"Firecracker","iconic":false},{"desc":"2019 ou 2024 — Kyle Gellis ; roulée à la Tabacalera La iSLA, Santiago, et chez NACSA, Estelí","name":"Gellis Family Cigars","iconic":false},{"desc":"1986 — marque de J.C. Newman, roulée par la famille Fuente à la Tabacalera A. Fuente, Santiago","name":"La Unica","iconic":false},{"desc":"1987, 1988 ou 1989 — Oscar Boruchin (Mike''s Cigars) ; roulée chez Quesada (MATASA), à Santiago","name":"Licenciados","iconic":false},{"desc":"Altadis U.S.A. — Onyx Reserve (2000) roulée à La Romana ; lignes Nicaragua chez A.J. Fernandez, à Estelí","name":"Onyx","iconic":false},{"desc":"1772, Delft — relancée en 2022 par United Cigars ; roulée chez Kelner Boutique Factory, à Santiago","name":"Red Anchor","iconic":false},{"desc":"Exclusivité de Neptune Cigars — roulée chez ABAM, à Villa Mella (Santo Domingo Norte) ; tripe mêlée","name":"Secret Blend of Cuba","iconic":false},{"desc":"2013 — Ventura Cigar Company (Kretek International) ; façonnée en République dominicaine, version Nicaragua à Condega","name":"Psyko Seven","iconic":false},{"desc":"1898 ou 1911 — détaillant de Philadelphie (famille Levin) ; bundles dominicains, fabriques non nommées","name":"Holt''s Cigar Company","iconic":false},{"desc":"2022 — le fils du fondateur de CAO ; Casa Carrillo (ex-La Alianza), NACSA, My Father","name":"Ozgener Family Cigars","iconic":false}]',
  `updated_at` = NOW()
 WHERE `id` = 'dominican';

-- ── Les sceaux des champs réécrits, calculés depuis les colonnes françaises ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` WHEN 'celebrities' THEN b.`celebrities` ELSE b.`gamme` END), 'machine', NULL, NOW()
  FROM `brands` b
  JOIN (SELECT 'Rocky Patel' hote, 'history' champ
        UNION ALL SELECT 'Ozgener Family Cigars' hote, 'gamme' champ
        UNION ALL SELECT 'Ozgener Family Cigars' hote, 'history' champ
        UNION ALL SELECT 'Miami Cigar & Co.' hote, 'history' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

