-- ── Contrôle : chaque ligne doit valoir 1 ──
SELECT 'Rocky Patel' AS hote, 'fr' AS lang, 'pays' AS quoi, (CAST(`country_id` AS BINARY) = CAST('honduras' AS BINARY)) AS ok FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('El Paraiso, Danlí, Honduras, sous-louée aux Plasencia (jusqu''à 78 000 par jour) ; TaviCusa (Tabacalera Villa Cuba), Estelí, Nicaragua, usine de Patel (26 000 à 28 000) — PCA, mars 2024' AS BINARY)) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('C''est aussi là que l''atlas range cette fiche : la Premium Cigar Association écrit en mars 2024 que la plus grande part des Rocky Patel sort d''El Paraiso, à Danlí (jusqu''à environ 78 000 cigares par jour, dit Nish Patel, vice-président exécutif), contre 26 000 à 28 000 à TaviCusa, à Estelí. Le pays d''une fiche désigne l''essentiel de la production, pas sa totalité : Emerald, Year of the Snake, Thirtieth et Sapphire sont roulées à TaviCusa, dit Cigar Coop, et une usine plus grande est annoncée au Nicaragua ; le site de la maison range en 2025 trente entrées au Nicaragua et dix-huit au Honduras.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Cela rappelle ce que le champ des fabriques de cette fiche dit déjà : le pays d''une fiche désigne l''essentiel de la production, pas sa totalité.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('It is also where the atlas files this entry: the Premium Cigar Association writes in March 2024 that the largest share of Rocky Patel cigars comes out of El Paraiso, in Danlí (up to about 78 000 cigars a day, says Nish Patel, executive vice-president), against 26 000 to 28 000 at TaviCusa, in Estelí. An entry''s country designates the bulk of the production, not all of it: Emerald, Year of the Snake, Thirtieth and Sapphire are rolled at TaviCusa, says Cigar Coop, and a larger factory is announced in Nicaragua; the house''s website files, in 2025, thirty entries under Nicaragua and eighteen under Honduras.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('It is a reminder of what this entry''s factory field already says: an entry''s country designates the bulk of the production, not all of it.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Es también allí donde el atlas clasifica esta ficha: la Premium Cigar Association escribe en marzo de 2024 que la mayor parte de los Rocky Patel sale de El Paraiso, en Danlí (hasta unos 78 000 puros al día, dice Nish Patel, vicepresidente ejecutivo), frente a 26 000 a 28 000 en TaviCusa, en Estelí. El país de una ficha designa lo esencial de la producción, no su totalidad: Emerald, Year of the Snake, Thirtieth y Sapphire se lían en TaviCusa, dice Cigar Coop, y se anuncia una fábrica más grande en Nicaragua; el sitio de la casa clasifica en 2025 treinta entradas en Nicaragua y dieciocho en Honduras.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Recuerda lo que el campo de fábricas de esta ficha ya dice: el país de una ficha designa lo esencial de la producción, no su totalidad.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Auch dort ordnet der Atlas diesen Eintrag ein: Die Premium Cigar Association schreibt im März 2024, dass der größte Teil der Rocky-Patel-Zigarren aus El Paraiso in Danlí kommt (bis zu etwa 78 000 Zigarren am Tag, sagt Nish Patel, Executive Vice President), gegenüber 26 000 bis 28 000 bei TaviCusa in Estelí. Das Land eines Eintrags bezeichnet den Hauptteil der Fertigung, nicht ihre Gesamtheit: Emerald, Year of the Snake, Thirtieth und Sapphire werden bei TaviCusa gerollt, sagt Cigar Coop, und eine größere Fabrik ist in Nicaragua angekündigt; die Website des Hauses ordnet 2025 dreißig Einträge Nicaragua und achtzehn Honduras zu.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Das erinnert an das, was das Fabrikfeld dieses Eintrags bereits sagt: Das Land eines Eintrags bezeichnet den Hauptteil der Fertigung, nicht ihre Gesamtheit.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('本图集也把本条目归入洪都拉斯：Premium Cigar Association 于2024年3月写道，Rocky Patel 雪茄的大部分出自丹利的 El Paraiso（据执行副总裁 Nish Patel 称，每天可达约78 000支雪茄），而埃斯特利的 TaviCusa 为26 000至28 000支。一条条目的国别指的是产量的主体，而非全部：Emerald、Year of the Snake、Thirtieth 与 Sapphire 在 TaviCusa 卷制，据 Cigar Coop 称；另已宣布将在尼加拉瓜设立一家更大的工厂；该公司网站在2025年把三十个条目归在尼加拉瓜，十八个归在洪都拉斯。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('它提醒了本条目工厂一栏早已写明的事：一条条目的国别指的是产量的主体，而非全部。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('وهناك أيضًا يصنّف الأطلس هذه البطاقة: تكتب Premium Cigar Association في مارس 2024 أنّ الحصّة الكبرى من سيجارات Rocky Patel تخرج من El Paraiso في دانلي (حتى نحو 78 000 سيجار في اليوم، بحسب Nish Patel، نائب الرئيس التنفيذي)، مقابل 26 000 إلى 28 000 في TaviCusa في إستيلي. وبلد البطاقة يدلّ على معظم الإنتاج لا على كلّه: تُلفّ Emerald وYear of the Snake وThirtieth وSapphire في TaviCusa، بحسب Cigar Coop، ويُعلَن عن مصنع أضخم في نيكاراغوا؛ ويصنّف موقع الدار في 2025 ثلاثين بندًا في نيكاراغوا وثمانية عشر في هندوراس.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('وفي ذلك تذكير بما يقوله حقل المصانع في هذه البطاقة أصلًا: بلد البطاقة يدلّ على معظم الإنتاج لا على كلّه.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Rocky Patel', 'fr', 'source', (LOCATE(CAST('premiumcigars.org « Rocky Patel Premium Cigars: Always Innov' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rocky Patel'
UNION ALL SELECT 'Ozgener Family Cigars', 'fr', 'limited_eds : Oz Family World Cup 2026', (JSON_CONTAINS(`limited_eds`, '"Oz Family World Cup 2026"')) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'fr', 'pays', (CAST(`country_id` AS BINARY) = CAST('dominican' AS BINARY)) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('L''atlas range la fiche en République dominicaine, où sont roulées trois des cinq lignes courantes, dont Bosphorus, la première ; aucune page ne donne de volume par fabrique. En octobre 2026, smokingpipes.com dit encore Bosphorus roulée chez Pichardo, au Nicaragua, alors que la maison la dit faite à Tabacalera La Alianza.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La fiche reste classée au Nicaragua, mais trois des cinq lignes courantes sortent de République dominicaine.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('The atlas files the entry in the Dominican Republic, where three of the five current lines are rolled, Bosphorus, the first, among them; no page gives a volume per factory. In October 2026, smokingpipes.com still says Bosphorus is rolled at Pichardo, in Nicaragua, whereas the house says it is made at Tabacalera La Alianza.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The entry remains classified in Nicaragua, but three of the five current lines come out of the Dominican Republic.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('El atlas clasifica la ficha en la República Dominicana, donde se lían tres de las cinco líneas actuales, entre ellas Bosphorus, la primera; ninguna página da un volumen por fábrica. En octubre de 2026, smokingpipes.com sigue diciendo que Bosphorus se lía en Pichardo, en Nicaragua, mientras que la casa dice que se hace en Tabacalera La Alianza.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La ficha sigue clasificada en Nicaragua, pero tres de las cinco líneas actuales salen de la República Dominicana.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Der Atlas ordnet den Eintrag in der Dominikanischen Republik ein, wo drei der fünf laufenden Linien gerollt werden, darunter Bosphorus, die erste; keine Seite nennt ein Volumen je Fabrik. Im Oktober 2026 sagt smokingpipes.com weiterhin, Bosphorus werde bei Pichardo in Nicaragua gerollt, während es nach Angabe des Hauses bei Tabacalera La Alianza gefertigt wird.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Der Eintrag bleibt in Nicaragua eingeordnet, aber drei der fünf laufenden Linien kommen aus der Dominikanischen Republik.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('本图集将该词条归入多米尼加共和国，五个现行系列中有三个在那里卷制，其中包括首个系列 Bosphorus；没有任何页面给出各工厂的产量。2026年10月，smokingpipes.com 仍称 Bosphorus 在尼加拉瓜的 Pichardo 卷制，而该公司称其在 Tabacalera La Alianza 制造。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('词条仍归入尼加拉瓜，但五个现行系列中有三个出自多米尼加共和国。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('ويصنّف الأطلس البطاقة في جمهورية الدومينيكان، حيث يُلفّ ثلاثة من الخطوط الخمسة الجارية، ومنها Bosphorus، الخطّ الأوّل؛ ولا تذكر أيّ صفحة حجم الإنتاج لكل مصنع. وفي تشرين الأول/أكتوبر 2026 لا يزال smokingpipes.com يقول إنّ Bosphorus يُلفّ لدى Pichardo في نيكاراغوا، في حين تقول الدار إنه يُصنع لدى Tabacalera La Alianza.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('وتبقى البطاقة مصنّفة في نيكاراغوا، لكنّ ثلاثة من الخطوط الخمسة الجارية تخرج من جمهورية الدومينيكان.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
UNION ALL SELECT 'Ozgener Family Cigars', 'fr', 'gamme Bosphorus', (JSON_CONTAINS(JSON_EXTRACT(`gamme`, '$[*].name'), '"Bosphorus"')) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
