SELECT (SELECT COUNT(*) FROM `translation_status` t JOIN `brands` b ON b.`name` = t.`entite_id` AND t.`entite` = 'brands'
         WHERE t.`source_hash` <> SHA1(CASE t.`champ` WHEN 'history' THEN b.`history` WHEN 'celebrities' THEN b.`celebrities` ELSE b.`gamme` END)
           AND t.`champ` IN ('history', 'gamme', 'celebrities') AND b.`name` IN ('Rocky Patel','Ozgener Family Cigars','Miami Cigar & Co.')) = 0 AS sceaux_a_jour,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `producer_countries` p ON p.`id` = t.`entite_id` AND t.`entite` = 'producer_countries'
         WHERE t.`champ` = 'notes' AND t.`source_hash` <> SHA1(p.`notes`) AND p.`id` IN ('nicaragua','honduras','dominican')) = 0 AS sceaux_pays_a_jour,
       (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 259') AS journal_non_tronque;
